# Claude Code: per-agent worktrees and personal, uncommitted settings
.claude/worktrees/
.claude/settings.local.json
CLAUDE.local.md
===
name: check

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version-file: .nvmrc
          cache: npm
      - run: npm ci
      - run: npm run check
      - run: npm run build
#!/bin/sh
# Runs the same gate as CI (CI also runs `npm run build`). Enabled per clone with: git config core.hooksPath .githooks
exec npm run -s check
{
  // Formatting (including line wrapping) is oxfmt's job; markdownlint checks structure.
  "config": {
    "MD013": false,
    "relative-links": true,
  },
  "customRules": ["markdownlint-rule-relative-links"],
  "globs": ["**/*.md"],
  // Also skips .gitignore'd paths, such as agent worktrees under .claude/worktrees/.
  "gitignore": true,
  "ignores": ["**/node_modules/**", "**/dist/**"],
}
{
  "$schema": "./node_modules/oxfmt/configuration_schema.json",
  "ignorePatterns": []
}

